"""Build the review from actual screenshots/recordings; never edits game assets."""
from pathlib import Path
import html,json
root=Path(__file__).resolve().parents[1]
e=root/'reports/evidence/campaign-polish'
prefix='evidence/campaign-polish/'
def img(file,label):
    src=prefix+file
    return f'<a href="{src}" target="_blank"><img loading="lazy" src="{src}" alt="{html.escape(label)}"></a>'
def pair(name,label):
    return '<article class="pair"><h3>'+label+'</h3><div class="two">'+''.join('<figure>'+img(v+'/'+name+'.png',label+' — '+ru)+f'<figcaption>{ru}</figcaption></figure>' for v,ru in [('before','До'),('after','После')])+'</div></article>'
def video(name,title,desc):
    return f'<article><h3>{title}</h3><video controls playsinline preload="metadata" src="{prefix}video/{name}.mp4"></video><p class="muted">{desc}</p></article>'
comparisons=[('ui-main','Естественная посадка знамён'),('ui-map','Карта и названия регионов'),('1-3-0','Каменная арка и опоры'),('2-1-4468','Декор и указатель'),('2-2-2700','Свободный проход под кладкой'),('3-1-450','Кратер виден заранее; лава уходит под берег'),('3-1-1350','Цельный рельеф'),('3-2-900','Убрана бесполезная низина'),('3-2-3600','Выход беса и пространство патруля')]
rows=json.loads((e/'after/coverage.json').read_text(encoding='utf-8'))
galleries=[]
for level in dict.fromkeys(r['level'] for r in rows):
    group=[r for r in rows if r['level']==level]
    galleries.append(f'<details><summary>{level} · {len(group)} положений камеры</summary><div class="windows">'+''.join('<figure>'+img('after/'+r['id']+'.png',r['id'])+f'<figcaption>X={r["x"]}</figcaption></figure>' for r in group)+'</div></details>')
body='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MARICRAFT · Полировка кампании</title><style>
:root{color-scheme:dark;font:17px/1.55 system-ui,sans-serif;background:#131b20;color:#f1e8d4}*{box-sizing:border-box}body{margin:0}main{max-width:1280px;margin:auto;padding:40px 24px 80px}a{color:#f8c879}h1{font-size:clamp(32px,5vw,62px);line-height:1.1;margin:10px 0 20px}h2{font-size:29px;margin:56px 0 18px}h3{font-size:20px;margin:18px 0 12px}.eyebrow{letter-spacing:.14em;text-transform:uppercase;color:#d7ad70}.lead{max-width:850px;font-size:20px}.muted,figcaption{color:#b7bdbe;font-size:14px}nav{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}nav a,.button{padding:9px 14px;border:1px solid #52616a;border-radius:7px;text-decoration:none;background:#223139}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:28px 0}.stats div{padding:18px;background:#223139;border-radius:8px}.stats b{display:block;font-size:29px;color:#f8c879}.notice{border-left:3px solid #b8793e;padding:12px 18px;background:#2c2923}.two,.clips{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.pair{margin:28px 0 40px}figure{margin:0}img,video{width:100%;height:auto;display:block;border-radius:5px;background:#0b1014}figcaption{padding:7px 0}.windows{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding-top:16px}details{border-top:1px solid #45525a;padding:14px 0}summary{cursor:pointer;font-weight:600}.wide{max-width:960px}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:9px 12px;border-bottom:1px solid #45525a;text-align:left}.scroll{overflow-x:auto}code{overflow-wrap:anywhere}@media(max-width:700px){main{padding:24px 16px 50px}.two,.clips,.windows{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}h2{font-size:25px;margin-top:38px}.lead{font-size:18px}}
</style><main><div class="eyebrow">MARICRAFT · 06 ноября 2026</div><h1>Девять уровней.<br>Одна цельная кампания.</h1><p class="lead">Исправленные маршруты и опоры, заметные опасности, стреляющие бесы и запертые арены. Ниже — реальные кадры и записи рабочего Godot-проекта.</p><nav><a href="#changes">До / после</a><a href="#motion">В движении</a><a href="#routes">Прохождения</a><a href="#world">Все участки</a><a href="#tests">Проверки</a><a href="../exports/campaign-polish-release/">Играть в Web</a><a href="../docs/CAMPAIGN_POLISH_REPORT.md">Полный отчёт</a></nav><div class="stats"><div><b>12 HP</b>у Рагнароса</div><div><b>0,60 с</b>перезарядка магии</div><div><b>108</b>основных проходов</div><div><b>9 / 9</b>карт на три звезды малым</div></div><p class="notice">Тело и молот Рагнароса пока прототипные: отдельный P07 v03 уже подготовлен и ожидает художественной приёмки и подключения. Эти записи не выдают временную модель за готовую графику.</p><h2 id="changes">Сравнение до и после</h2><p>Одинаковые положения камеры, настоящий рендер Godot. Нажмите на кадр, чтобы открыть исходное разрешение.</p>'''
body+=''.join(pair(*p) for p in comparisons)
body+='<h2 id="motion">Патрули, атаки и опоры в движении</h2><p>Короткие локальные сценарии в настоящих сценах. Начальное положение подготовлено тестом; патруль, снаряды, прыжок уклонения и оседание тела исполняет игровой код. Это не непрерывное прохождение.</p><div class="clips">'
body+=video('pipe-patrol','3-2 · Бес свободно патрулирует','12 секунд. Выход влево; около 143 единиц между крайними точками, без дрожания у трубы.')
body+=video('imp-ranged','3-1 · Подготовка, выстрел, уклонение','8 секунд. Подготовка 0,65 с, небольшой снаряд 156 ед./с. Уклонение обычным прыжком без защиты тестового режима.')
body+=video('corpse-1-3','1-3 · Побеждённый вожак','4 секунды. В локальной проверке смерть вызвана тестом; положение стоп и оседание определяет реальная поверхность.')
body+=video('corpse-2-3','2-3 · Побеждённый главарь','4 секунды. Визуальная ветвь опирается на грунт; коллизия босса не двигается ради картинки.')
body+='</div><h2 id="routes">Непрерывные прохождения Недр</h2><p>Малый человек, без магии, полёта и неуязвимости. Только движение, прыжки и обычные трубы. Каждая запись содержит целый маршрут с дополнительными наградами; три звезды получены игровой логикой. Кадры записаны при физике 60 Гц, видео — 15 кадров/с.</p>'
for name,title in [('3-1','3-1 · 107 из 112 монет'),('3-2','3-2 · 180 из 215 монет, включая шахту'),('3-3','3-3 · 36 из 39 монет и Рагнарос с 12 HP')]:body+='<div class="wide">'+video(name,title,'Можно перемотать к интересующему участку. Звук в PNG-записях не захватывался; звук игры этой видеодорожкой не оценивается.')+'</div>'
body+='<h2>Арены и интерфейс</h2><div class="two">'
for name,label in [('mechanics-60/arena-locked-1-3-0.png','1-3 · Вход закрыт'),('mechanics-60/arena-locked-2-3-0.png','2-3 · Вход закрыт'),('mechanics-30/hammer-side-1-hp-12.png','3-3 · Головка справа, 640×360'),('ui/free-map-640.png','Карта · реальные подписи и узлы, 640×360')]:body+='<figure>'+img(name,label)+'<figcaption>'+label+'</figcaption></figure>'
body+='</div><h2 id="world">Полный обзор камеры</h2><p>100 перекрывающихся окон, включая грот и шахты. Это осмотр геометрии и слоёв с отключённым HUD; живые сцены с интерфейсом показаны выше.</p>'+''.join(galleries)
body+='''<h2 id="tests">Что подтверждено</h2><div class="scroll"><table><tr><th>Проверка</th><th>Результат</th></tr><tr><td>Оба героя, три формы, 30/60</td><td>108 основных маршрутов завершены</td></tr><tr><td>Малый без магии</td><td>Три звезды во всех девяти картах</td></tr><tr><td>Блоки третьей главы</td><td>462 ситуации и 96 открытий сундуков на каждой частоте</td></tr><tr><td>Три арены</td><td>Запирание, смерть, повтор, загрузка побеждённого босса, единственная награда</td></tr><tr><td>Web release</td><td>Все девять уровней, финал, reload, повтор; ошибок runtime нет</td></tr><tr><td>Web бой 3-3</td><td>29,87 / 59,55 FPS при лимитах 30 / 60 на этой машине</td></tr><tr><td>Godot GUI</td><td>F8 подтверждён. Текущая проверка F5 остановлена защитой от ввода поверх активного пользователя</td></tr></table></div><p>Нативные графические сценарии и Web — настоящие запуски игры. Они не называются ручным прохождением через редактор. HTTPS и слабые устройства не проверены.</p><p><a href="evidence/campaign-polish/verification.json">Протокол геометрии и SHA256</a> · <a href="../docs/CAMPAIGN_POLISH_REPORT.md">Подробные изменения, параметры и команды</a> · <a href="../docs/NATIVE_LAUNCH.md">Как открыть проект</a></p><h2>Открыть в Godot</h2><p>Godot 4.7.2 Standard → «Импортировать» → <code>D:/Projects/MARICRAFT/project.godot</code> → открыть → <b>F5</b>. Для остановки — <b>F8</b>. Для осмотра уровня: F1 → «Начать тестовую сессию» → «Заново · нужный уровень». Браузер и сервер для F5 не нужны.</p><p class="muted">Сохранения Web и настольной игры раздельные. Исходный P07 и принятые PNG/аудио/шрифты не перезаписывались. Новая локация не начиналась.</p></main></html>'''
(root/'reports/CAMPAIGN_POLISH_REVIEW.html').write_text(body,encoding='utf-8')
print('Review created; screenshot windows:',len(rows))
